ALTER TABLE "Consultas" ADD COLUMN IF NOT EXISTS "Revisao" integer NOT NULL DEFAULT 0;
ALTER TABLE "ListasEspera" ADD COLUMN IF NOT EXISTS "Prioridade" integer NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS "Salas" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Nome" text NOT NULL, "Ativa" boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "Jornadas" ("ConsultaId" integer PRIMARY KEY REFERENCES "Consultas"("Id") ON DELETE CASCADE, "SalaId" integer NULL REFERENCES "Salas"("Id"), "Duracao" integer NOT NULL DEFAULT 30, "Tele" boolean NOT NULL DEFAULT false, "PagamentoConferido" boolean NOT NULL DEFAULT false, "Revisao" integer NOT NULL DEFAULT 0, "CadastroEm" timestamptz NULL, "CheckInEm" timestamptz NULL, "ChegadaEm" timestamptz NULL, "InicioEm" timestamptz NULL, "FimEm" timestamptz NULL, "ConsentimentoEm" timestamptz NULL, "AtualizadoEm" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "Ofertas" ("Id" uuid PRIMARY KEY, "ListaEsperaId" integer NOT NULL REFERENCES "ListasEspera"("Id") ON DELETE CASCADE, "MedicoId" integer NOT NULL, "Data" date NOT NULL, "Horario" text NOT NULL, "Estado" text NOT NULL, "ExpiraEm" timestamptz NOT NULL, "CriadoEm" timestamptz NOT NULL, "NotificadaEm" timestamptz NULL, "ConsultaId" integer NULL, "Tentativas" integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "ChavesClinicas" ("Id" uuid PRIMARY KEY, "UsuarioId" text NOT NULL, "Publica" text NOT NULL, "Impressao" text NOT NULL, "CriadoEm" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "FormulariosClinicos" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "MedicoId" integer NOT NULL, "Versao" integer NOT NULL, "Titulo" text NOT NULL, "Perguntas" text NOT NULL, "CriadoEm" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "RespostasClinicas" ("Id" uuid PRIMARY KEY, "ConsultaId" integer NOT NULL REFERENCES "Consultas"("Id") ON DELETE CASCADE, "FormularioId" integer NOT NULL REFERENCES "FormulariosClinicos"("Id"), "MedicoId" integer NOT NULL, "PacienteId" integer NOT NULL, "Envelope" text NOT NULL, "CriadoEm" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "SinaisTele" ("Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "ConsultaId" integer NOT NULL REFERENCES "Consultas"("Id") ON DELETE CASCADE, "UsuarioId" text NOT NULL, "Protegido" text NOT NULL, "CriadoEm" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "LinksConsulta" ("Id" uuid PRIMARY KEY, "ConsultaId" integer NOT NULL REFERENCES "Consultas"("Id") ON DELETE CASCADE, "Snapshot" text NOT NULL, "ExpiraEm" timestamptz NOT NULL, "UsadoEm" timestamptz NULL);
CREATE TABLE IF NOT EXISTS "MobileTickets" ("Id" uuid PRIMARY KEY, "ConsultaId" integer NOT NULL REFERENCES "Consultas"("Id") ON DELETE CASCADE, "Principal" text NOT NULL, "ExpiraEm" timestamptz NOT NULL, "Usado" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS "MedicoesOperacionais" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Data" date NOT NULL, "Periodo" text NOT NULL, "Consultas" integer NOT NULL, "Faltas" integer NOT NULL, "MinutosRecepcao" integer NOT NULL, "Fonte" text NOT NULL);
CREATE TABLE IF NOT EXISTS "PepEventos" ("Id" uuid PRIMARY KEY, "ConsultaId" integer NOT NULL REFERENCES "Consultas"("Id") ON DELETE CASCADE, "Estado" text NOT NULL, "Data" date NOT NULL, "Horario" text NOT NULL, "CriadoEm" timestamptz NOT NULL, "EntregueEm" timestamptz NULL, "TentarEm" timestamptz NULL, "Tentativas" integer NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Ofertas_Slot" ON "Ofertas" ("MedicoId","Data","Horario") WHERE "Estado" = 'Aberta';
CREATE INDEX IF NOT EXISTS "IX_Ofertas_ListaEsperaId" ON "Ofertas" ("ListaEsperaId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_ChavesClinicas_UsuarioId_Impressao" ON "ChavesClinicas" ("UsuarioId","Impressao");
CREATE INDEX IF NOT EXISTS "IX_SinaisTele_ConsultaId_Id" ON "SinaisTele" ("ConsultaId","Id");
CREATE INDEX IF NOT EXISTS "IX_RespostasClinicas_ConsultaId" ON "RespostasClinicas" ("ConsultaId");
ALTER TABLE "PepEventos" ADD COLUMN IF NOT EXISTS "PacienteId" integer NOT NULL DEFAULT 0;
ALTER TABLE "PepEventos" ADD COLUMN IF NOT EXISTS "MedicoId" integer NOT NULL DEFAULT 0;
UPDATE "PepEventos" e SET "PacienteId"=c."PacienteId", "MedicoId"=c."MedicoId" FROM "Consultas" c WHERE c."Id"=e."ConsultaId" AND (e."PacienteId"=0 OR e."MedicoId"=0);
ALTER TABLE "RespostasClinicas" ADD COLUMN IF NOT EXISTS "AutorizadaEm" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "Jornadas" ADD COLUMN IF NOT EXISTS "PresencaConfirmadaEm" timestamptz NULL;
ALTER TABLE "ChavesClinicas" ADD COLUMN IF NOT EXISTS "RevogadaEm" timestamptz NULL;
